head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//elw발행사
scwin.vScrenID = "ULDINS90800.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : elw발행사  조회 한다.
 ***********************************************/
scwin.ins_search = function(isurnm) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS90800_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listElwIssInstCdInquiry" + "&{P}ISUR_NM=" + isurnm;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    var ISUR_CD = dts_List.getCellData(row, "ISUR_CD");
    var COM_NM = dts_List.getCellData(row, "COM_NM");
    var WRNT_ISUR_CD = dts_List.getCellData(row, "WRNT_ISUR_CD");
    var WRNT_ISUR_NM = dts_List.getCellData(row, "WRNT_ISUR_NM");
    $c.frame.path("../").ins_popupRtn_val4(ISUR_CD, COM_NM, WRNT_ISUR_CD, WRNT_ISUR_NM);
    await $c.frame.CloseFrame();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.btn_search_onclick = function() {
    scwin.ins_search(txb_ISUR_NM.getValue());
};
scwin.txb_ISUR_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_ISUR_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search(txb_ISUR_NM.getValue());
        } else {

        }
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    txb_ISUR_NM.focus();
};
